import os

cache = os.environ['REPRO_DATA_CACHE']
for name in ['cancer', 'mammo', 'mushroom', 'data', 'papers', 'hf']:
    p = os.path.join(cache, name)
    if os.path.isdir(p):
        try:
            ents = sorted(os.listdir(p))
        except Exception as e:
            ents = [str(e)]
        print(name, '->', ents[:20], '...' if len(ents) > 20 else '')
        for e in ents[:8]:
            fp = os.path.join(p, e)
            if os.path.isfile(fp):
                print('    ', e, os.path.getsize(fp))
    else:
        print(name, 'FILE', os.path.getsize(p))
